# Get more detailed data including intraday
curl -sL --max-time 10 'https://query2.finance.yahoo.com/v8/finance/chart/0056.TW?interval=5m&range=1d' \
  -H 'User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36' 2>&1 | python3 -c "
import sys, json, re
data = sys.stdin.read()
# Parse the JSON response manually without json module (might be garbled)
# Extract key values with regex
m = re.search(r'\"regularMarketPrice\":([\d.]+)', data)
if m: print(f'最新價: {m.group(1)}')
m = re.search(r'\"chartPreviousClose\":([\d.]+)', data)
if m: print(f'昨收: {m.group(1)}')
m = re.search(r'\"regularMarketDayHigh\":([\d.]+)', data)
if m: print(f'最高: {m.group(1)}')
m = re.search(r'\"regularMarketDayLow\":([\d.]+)', data)
if m: print(f'最低: {m.group(1)}')
m = re.search(r'\"regularMarketVolume\":([\d,]+)', data)
if m: print(f'成交量: {m.group(1)}')
m = re.search(r'\"open\":\[\[([\d.]+)\]\]', data)
if m: print(f'開盤: {m.group(1)}')
" 2>&1
